#include "processing/document_result.h"
#include "core/app_error.h"
#include "core/crypto.h"
#include "../test_support.h"
#include <nlohmann/json.hpp>

namespace {
using Json = nlohmann::json;
Json Example() {
    // Generated by the real Python parser; offsets independently checked as six code points.
    Json chunk = {{"chunk_id", "aa4e40dcbab80b3b0b0adb3f8765f0e4ab14173c1f832d10fe00f5f50c49cf9b"},
        {"file_id", std::string(32, 'a')}, {"version_id", std::string(32, 'b')},
        {"source_sha256", "d5347ac8741417692a1c1ce7a4e18ca6057709fc6c5ce81e8c0abc763f68c4af"},
        {"parser_revision", "utf8-lines-v1"}, {"text", "甲乙\nabc"},
        {"char_start", 0}, {"char_end", 6}, {"line_start", 1}, {"line_end", 2}};
    return {{"file_id", chunk["file_id"]}, {"version_id", chunk["version_id"]},
        {"source_sha256", chunk["source_sha256"]}, {"parser_revision", chunk["parser_revision"]},
        {"page_count", 0}, {"pages_without_text", Json::array()}, {"chunks", Json::array({chunk})}};
}
void Reidentify(Json& result) {
    for (auto& chunk : result["chunks"]) {
        chunk["parser_revision"] = result["parser_revision"];
        Json id = Json::array({result["parser_revision"], result["file_id"],
                              result["version_id"], result["source_sha256"]});
        if (chunk.contains("page")) id.push_back(chunk["page"]);
        id.push_back(chunk["char_start"]); id.push_back(chunk["char_end"]);
        const auto bytes = id.dump();
        chunk["chunk_id"] = Sha256Hex(bytes.data(), bytes.size());
    }
}
}

TEST_CASE(document_result_accepts_python_identity_and_unicode_locations) {
    auto result = Example();
    auto validated = ValidateDocumentResult(result);
    CHECK(validated.char_count == 6);
    CHECK(validated.fingerprint.size() == 64);
    CHECK(validated.fingerprint == ValidateDocumentResult(result).fingerprint);
    result["chunks"][0]["text"] = "丙丁\nxyz";
    CHECK(validated.fingerprint != ValidateDocumentResult(result).fingerprint);
}

TEST_CASE(document_result_rejects_forged_identity_types_counts_and_locations) {
    for (const auto& field : {"chunk_id", "file_id", "version_id", "source_sha256", "parser_revision"}) {
        auto result = Example(); result["chunks"][0][field] = "forged";
        CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
    }
    for (const Json& value : {Json(-1), Json(1.0), Json(true), Json("1"), Json(2000001)}) {
        auto result = Example(); result["chunks"][0]["char_start"] = value;
        CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
    }
    for (const std::string field : {"char_end", "line_start", "line_end"}) {
        auto result = Example(); result["chunks"][0][field] = 99;
        Reidentify(result);
        CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
    }
    auto result = Example(); result["chunks"].push_back(result["chunks"][0]);
    CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
    result = Example(); result["unknown"] = true;
    CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
    result = Example(); result["chunks"] = Json::array();
    CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
}

TEST_CASE(document_result_rejects_controls_invalid_utf8_and_oversized_chunks) {
    for (const std::string& text : {std::string("\xff"), std::string("\xc0\xaf"),
             std::string("\xed\xa0\x80"), std::string("\xc2\x80"), std::string("a\rbc"),
             std::string("abc\0def", 7), std::string(1201, 'a'), std::string("  \n  ")}) {
        auto result = Example(); result["chunks"][0]["text"] = text;
        result["chunks"][0]["char_end"] = text.size(); Reidentify(result);
        CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
    }
}

TEST_CASE(document_result_pdf_requires_complete_explicit_page_coverage) {
    auto result = Example(); result["parser_revision"] = "pypdf-6.21.0-lines-v1";
    result["page_count"] = 3; result["pages_without_text"] = Json::array({1,3});
    result["chunks"][0]["page"] = 2; Reidentify(result);
    CHECK(ValidateDocumentResult(result).char_count == 6);
    for (const Json& pages : {Json::array(), Json::array({1}), Json::array({1,2,3}),
                            Json::array({1,1,3}), Json::array({3,1}), Json::array({1,4})}) {
        auto invalid = result; invalid["pages_without_text"] = pages;
        CHECK_THROWS_CODE(ValidateDocumentResult(invalid), "invalid_result");
    }
    result["page_count"] = 301;
    CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
}

TEST_CASE(document_result_contiguous_chunks_preserve_newlines_and_four_byte_unicode) {
    auto result = Example(); const auto prototype = result["chunks"][0];
    result["chunks"] = Json::array();
    // Four code points in the first chunk, despite eleven UTF-8 bytes; newline belongs to line 1.
    auto first = prototype; first["text"] = "甲乙😀\n"; first["char_end"] = 4; first["line_end"] = 1;
    auto second = prototype; second["text"] = "abcdef"; second["char_start"] = 4;
    second["char_end"] = 10; second["line_start"] = 2; second["line_end"] = 2;
    auto third = second; third["text"] = "gh"; third["char_start"] = 10; third["char_end"] = 12;
    result["chunks"] = Json::array({first,second,third}); Reidentify(result);
    CHECK(ValidateDocumentResult(result).char_count == 12);
    result["chunks"][2]["line_start"] = 3;
    CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
}

TEST_CASE(document_result_accepts_real_python_pdf_page_identities) {
    // Python parse_pdf(test/fixtures/m1/sample.pdf, file_id='a'*32, version_id='b'*32).
    auto result = Example(); result["source_sha256"] = "96b602f6d4b99855125ade8fba314e07461f871926e74b8a6bfc4b842acee008";
    result["parser_revision"] = "pypdf-6.21.0-lines-v1"; result["page_count"] = 2;
    auto first = result["chunks"][0];
    first["source_sha256"] = result["source_sha256"]; first["parser_revision"] = result["parser_revision"];
    first["text"] = "PAGE ONE"; first["page"] = 1; first["char_end"] = 8; first["line_end"] = 1;
    first["chunk_id"] = "5cbb45d8577e75c5f6b47e5733aa6002cb8f647de7aeee54edee3c99f2cb5f7c";
    auto second = first; second["text"] = "PAGE TWO"; second["page"] = 2;
    second["chunk_id"] = "d04c46d23faf6c4caa779fcbc02ba9a1f0944e33cdaf77ceb7ba981eff945f26";
    result["chunks"] = Json::array({first,second});
    CHECK(ValidateDocumentResult(result).char_count == 16);
    result["chunks"][1]["char_start"] = 8; result["chunks"][1]["char_end"] = 16;
    Reidentify(result);
    CHECK_THROWS_CODE(ValidateDocumentResult(result), "invalid_result");
}

TEST_CASE(document_result_enforces_aggregate_character_and_chunk_boundaries) {
    auto result = Example(); const auto prototype = result["chunks"][0];
    result["chunks"] = Json::array();
    // Exactly both aggregate maxima: 2,000 chunks of 1,000 characters.
    for (uint64_t index = 0; index < 2000; ++index) {
        auto chunk = prototype; chunk["text"] = std::string(1000, 'x');
        chunk["char_start"] = index * 1000; chunk["char_end"] = (index + 1) * 1000;
        chunk["line_end"] = 1; result["chunks"].push_back(chunk);
    }
    Reidentify(result);
    CHECK(ValidateDocumentResult(result).char_count == 2000000);
    // PDF page-local positions stay below the per-page bound while the total crosses it.
    auto excessive = result; excessive["parser_revision"] = "pypdf-6.21.0-lines-v1";
    excessive["page_count"] = 2;
    for (uint64_t index = 0; index < 2000; ++index) {
        auto& chunk = excessive["chunks"][index]; chunk["page"] = index / 1000 + 1;
        chunk["char_start"] = (index % 1000) * 1000; chunk["char_end"] = (index % 1000 + 1) * 1000;
    }
    Reidentify(excessive);
    CHECK(ValidateDocumentResult(excessive).char_count == 2000000);
    excessive["chunks"][1999]["text"] = std::string(1001, 'x');
    excessive["chunks"][1999]["char_end"] = 1000001; Reidentify(excessive);
    CHECK_THROWS_CODE(ValidateDocumentResult(excessive), "invalid_result");
    // Over chunk count without exceeding the character limit.
    excessive = Example(); excessive["chunks"] = Json::array();
    for (uint64_t index = 0; index < 2001; ++index) {
        auto chunk = prototype; chunk["text"] = "x"; chunk["char_start"] = index;
        chunk["char_end"] = index+1; chunk["line_end"] = 1; excessive["chunks"].push_back(chunk);
    }
    Reidentify(excessive);
    CHECK_THROWS_CODE(ValidateDocumentResult(excessive), "invalid_result");
}
